30 // Since we are detecting the CSR change by comparing the old value, we need to
31 // ensure the CSR is detected when the pipeline's Writeback stage is not
32 // stalled.  If it is stalled we want to hold the old value.
33 `define CONNECT_CSR(name, addr, val) \
34   logic [P.XLEN-1:0] prev_csr_``name; \
35   always_ff @(posedge clk) \
36     prev_csr_``name <= rvvi.csr[0][0][addr]; \
37   assign rvvi.csr_wb[0][0][addr] = (rvvi.csr[0][0][addr] != prev_csr_``name); \
38   assign rvvi.csr[0][0][addr] = valid ? val : prev_csr_``name;
